constexpr int H=8192; constexpr size_t W=20000; using Hist=std::array<long long,2*H+1>;
const int Z[64]={0,1,8,16,9,2,3,10,17,24,32,25,18,11,4,5,12,19,26,33,40,48,41,34,27,20,13,6,7,14,21,28,35,42,49,56,57,50,43,36,29,22,15,23,30,37,44,51,58,59,52,45,38,31,39,46,53,60,61,54,47,55,62,63};
std::vector<unsigned char> read(const fs::path&p){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("open "+p.string());return {std::istreambuf_iterator<char>(f),{}};}
struct Mark{std::vector<unsigned char> stripped,app2;int n=0;bool bad=false;};
Mark strip(const std::vector<unsigned char>&d){if(d.size()<4||d[0]!=255||d[1]!=216)throw std::runtime_error("SOI");Mark o;o.stripped.insert(o.stripped.end(),d.begin(),d.begin()+2);size_t p=2;while(p+1<d.size()){size_t s=p;if(d[p++]!=255)throw std::runtime_error("marker");while(p<d.size()&&d[p]==255)++p;unsigned m=d[p++];if(m==217){o.stripped.insert(o.stripped.end(),d.begin()+s,d.begin()+p);o.bad|=p!=d.size();return o;}if(m==216||m==1||(m>=208&&m<=215)){o.stripped.insert(o.stripped.end(),d.begin()+s,d.begin()+p);continue;}if(p+1>=d.size())throw std::runtime_error("length");size_t L=(size_t(d[p])<<8)|d[p+1],e=p+L;if(L<2||e>d.size())throw std::runtime_error("segment");if(m==218){o.stripped.insert(o.stripped.end(),d.begin()+s,d.end());o.bad|=d.size()<2||d[d.size()-2]!=255||d.back()!=217;return o;}if(m==226){++o.n;o.app2.assign(d.begin()+p+2,d.begin()+e);}else o.stripped.insert(o.stripped.end(),d.begin()+s,d.begin()+e);o.bad|=m==225||m==254||m==221;p=e;}throw std::runtime_error("EOI");}
double chi(const std::vector<int>&v,size_t b,size_t n){Hist h{};size_t e=std::min(v.size(),b+n);for(size_t i=b;i<e;++i)++h[H+v[i]];double c=0;int df=0;for(int s:{1,-1})for(int a=2;a<H;a+=2){long long x=h[H+s*a],y=h[H+s*(a+1)],t=x+y;if(t>=5){double q=double(x-y);c+=q*q/double(t);++df;}}return df?c/df:NAN;}
std::vector<int> coeffs(jpeg_decompress_struct&j,jvirt_barray_ptr*c){int mh=1,mv=1;for(int i=0;i<j.num_components;++i){mh=std::max(mh,j.comp_info[i].h_samp_factor);mv=std::max(mv,j.comp_info[i].v_samp_factor);}JDIMENSION nx=(j.image_width+8*mh-1)/(8*mh),ny=(j.image_height+8*mv-1)/(8*mv);std::vector<int>v;v.reserve(700000);for(JDIMENSION yy=0;yy<ny;++yy)for(JDIMENSION xx=0;xx<nx;++xx)for(int ci=0;ci<j.num_components;++ci){auto&cc=j.comp_info[ci];for(int vv=0;vv<cc.v_samp_factor;++vv){auto row=(*j.mem->access_virt_barray)((j_common_ptr)&j,c[ci],yy*cc.v_samp_factor+vv,1,FALSE);for(int hh=0;hh<cc.h_samp_factor;++hh){auto b=row[0][xx*cc.h_samp_factor+hh];for(int k=1;k<64;++k){int x=b[Z[k]];if(std::abs(x)>1&&std::abs(x)<H)v.push_back(x);}}}}return v;}
std::vector<unsigned char> reencode(jpeg_decompress_struct&src,jvirt_barray_ptr*c){jpeg_compress_struct d{};jpeg_error_mgr e{};d.err=jpeg_std_error(&e);jpeg_create_compress(&d);unsigned char*b=nullptr;unsigned long n=0;jpeg_mem_dest(&d,&b,&n);jpeg_copy_critical_parameters(&src,&d);d.optimize_coding=TRUE;jpeg_write_coefficients(&d,c);jpeg_finish_compress(&d);std::vector<unsigned char>o(b,b+n);free(b);jpeg_destroy_compress(&d);return o;}
uint64_t rs;uint64_t rng(){rs^=rs<<7;rs^=rs>>9;rs^=rs<<8;return rs;}
double plant(std::vector<int>v,int p){rs=0xD1B54A32D192ED03ULL+uint64_t(p);for(size_t i=0;i<std::min(W,v.size());++i){int s=v[i]<0?-1:1,a=std::abs(v[i]);v[i]=s*((a&~1)|int(rng()&1));}return chi(v,0,W);}
int main(int argc,char**argv){fs::path dir=argc>1?argv[1]:"resources/liber-primus";std::vector<unsigned char>icc;double mf=INFINITY,mw=INFINITY;int pf=-1,pw=-1;struct C{int p;double o,x;};std::vector<C>ctrl;for(int p=0;p<58;++p){char n[16];snprintf(n,sizeof(n),"%02d.jpg",p+17);auto raw=read(dir/n);auto m=strip(raw);if(m.n!=1||m.app2.size()!=2590||m.bad)throw std::runtime_error("markers p"+std::to_string(p));if(!p)icc=m.app2;else if(m.app2!=icc)throw std::runtime_error("ICC p"+std::to_string(p));jpeg_decompress_struct j{};jpeg_error_mgr e{};j.err=jpeg_std_error(&e);jpeg_create_decompress(&j);jpeg_mem_src(&j,const_cast<unsigned char*>(raw.data()),raw.size());jpeg_read_header(&j,TRUE);auto c=jpeg_read_coefficients(&j);auto v=coeffs(j,c);if(reencode(j,c)!=m.stripped)throw std::runtime_error("serialization p"+std::to_string(p));double f=chi(v,0,v.size()),w=INFINITY;for(size_t b=0;b<v.size();b+=W){size_t k=std::min(W,v.size()-b);if(k>=5000)w=std::min(w,chi(v,b,k));}if(f<mf){mf=f;pf=p;}if(w<mw){mw=w;pw=p;}if(p==50||p==55||p==57)ctrl.push_back({p,chi(v,0,W),plant(v,p)});jpeg_finish_decompress(&j);jpeg_destroy_decompress(&j);}std::string s="Artifex Software sRGB ICC Profile";if(std::search(icc.begin(),icc.end(),s.begin(),s.end())==icc.end())throw std::runtime_error("ICC label");if(mw<2.5)throw std::runtime_error("authentic window too flat");for(auto&c:ctrl)if(!(c.x<1.2&&c.x<c.o))throw std::runtime_error("plant");std::cout<<std::fixed<<std::setprecision(6)<<"PASS source_pages=58 exact_libjpeg_reserializations=58 shared_app2_total_bytes=2594\n"<<"PASS no_APP1_COM_DRI_or_post_EOI_payload=58/58\n"<<"authentic_min_full_chi2_per_df="<<mf<<" page=p"<<pf<<"\n"<<"authentic_min_20k_window_chi2_per_df="<<mw<<" page=p"<<pw<<"\n";for(auto&c:ctrl)std::cout<<"control_p"<<c.p<<" original_first20k="<<c.o<<" planted_random_lsb_first20k="<<c.x<<"\n";}
